  // 5. Bulk cell writes (cell edit and paste share this endpoint).
  router.put('/workbooks/:id/worksheets/:wid/cells', (req, res) => {
    const ws = requireWorksheet(db, req.params.id, req.params.wid);
    const changes = parseCellChanges(req.body);

    for (const change of changes) {
      if (change.row >= ws.row_count || change.col >= ws.col_count) {
        throw invalidBody(
          `Cell ${change.row},${change.col} is outside the worksheet structure (${ws.row_count}x${ws.col_count})`,
        );
      }
    }

    const violation = findValidationViolation(changes);
    if (violation) {
      res.status(409).json({ error: { code: violation.code, message: violation.message } });
      return;
    }

    res.json(applyCellChanges(db, ws, changes));
  });

  // 6. Whole-worksheet state import (undo/redo replay).
  router.put('/workbooks/:id/worksheets/:wid/state', (req, res) => {
    const ws = requireWorksheet(db, req.params.id, req.params.wid);
    const payload = asObject(req.body ?? {});
    const worksheet = importWorksheetState(db, ws, payload);
    const workbook = getWorkbookRow(db, ws.workbook_id);
    res.json({ updatedAt: workbook?.updated_at ?? new Date().toISOString(), worksheet });
  });

  // Selection persistence (contract §2.9): the last confirmed rectangle.
  router.put('/workbooks/:id/worksheets/:wid/selection', (req, res) => {
    const ws = requireWorksheet(db, req.params.id, req.params.wid);
    const selection = parseSelection(req.body);
    setSelection(db, ws, selection);
    res.json({ ok: true, selection });
  });

  // Worksheet rename / activation.
  router.patch('/workbooks/:id/worksheets/:wid', (req, res) => {
    const ws = requireWorksheet(db, req.params.id, req.params.wid);
    const body = asObject(req.body ?? {});
    res.json(patchWorksheet(db, ws, { name: body.name, isActive: body.isActive }));
  });

  return router;
}
